package com.bank.org;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BinaryTreeDemo {

    private static final Logger log = Logger.getLogger(BinaryTreeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build the branch hierarchy (root = Branch Manager).
        HierarchyNode officerA = new HierarchyNode("Officer-Anil", null, null);
        HierarchyNode officerB = new HierarchyNode("Officer-Bela", null, null);
        HierarchyNode deputyLeft = new HierarchyNode("Deputy-Rajesh", officerA, officerB);
        HierarchyNode deputyRight = new HierarchyNode("Deputy-Priya", null, null);
        HierarchyNode root = new HierarchyNode("BranchManager", deputyLeft, deputyRight);

        OrgTree tree = new OrgTree();
        log.info("Inorder listing of the hierarchy:");
        tree.inorder(root);

        log.info(() -> "Total people in hierarchy: " + tree.countNodes(root));
        log.info(() -> "Height (levels) of hierarchy: " + tree.height(root));
    }
}

