class HierarchyNode {
    private final String name;
    private final HierarchyNode left;   // at most one left child
    private final HierarchyNode right;  // at most one right child

    HierarchyNode(String name, HierarchyNode left, HierarchyNode right) {
        this.name = name;
        this.left = left;
        this.right = right;
    }

    String getName() { return name; }
    HierarchyNode getLeft() { return left; }
    HierarchyNode getRight() { return right; }
}

// ─── Would be in service/OrgTree.java in a real project ───
class OrgTree {

    private static final Logger log = Logger.getLogger(OrgTree.class.getName());

    // Inorder: left subtree, node, right subtree.
    void inorder(HierarchyNode node) {
        if (node == null) return;              // base case: empty branch
        inorder(node.getLeft());
        log.info(() -> "Visit: " + node.getName());
        inorder(node.getRight());
    }

    // Count every node recursively.
    int countNodes(HierarchyNode node) {
        if (node == null) return 0;
        return 1 + countNodes(node.getLeft()) + countNodes(node.getRight());
    }

    // Height = longest root-to-leaf path in number of levels.
    int height(HierarchyNode node) {
        if (node == null) return 0;
        return 1 + Math.max(height(node.getLeft()), height(node.getRight()));
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
